<?php
declare(strict_types=1);ini_set('serialize_precision','-1');
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/jwt_helper.php';
$base=rtrim((string)($argv[1]??'http://localhost/backend'),'/');$requests=max(10,min(200,(int)($argv[2]??40)));$concurrency=max(1,min(20,(int)($argv[3]??8)));
$c=db();$row=$c->query("SELECT u.id,u.email,cm.role,cm.company_id,cm.id membership_id,cm.version membership_version FROM company_memberships cm JOIN companies c ON c.id=cm.company_id AND c.status='ACTIVE' JOIN users u ON u.id=cm.user_id WHERE cm.status='ACTIVE' AND cm.role='ADMINISTRATOR' AND u.account_status='ACTIVE' AND u.email_verified_at IS NOT NULL ORDER BY cm.is_owner DESC,cm.id LIMIT 1")->fetch_assoc();if(!$row){fwrite(STDERR,"No active verified administrator membership is available for the benchmark.\n");exit(2);}$token=generateJwt($row,180);
$tests=[
'readiness'=>['url'=>'/health/ready.php','target'=>250,'auth'=>false],
'dashboard'=>['url'=>'/dashboard/overview.php','target'=>1000,'auth'=>true],
'invoice_page'=>['url'=>'/invoices/list_page.php?page=1&page_size=20','target'=>600,'auth'=>true],
'reports'=>['url'=>'/reports/overview.php?from='.date('Y-m-01').'&to='.date('Y-m-d'),'target'=>2000,'auth'=>true],
];
function httpBatch(string $url,string $token,bool $auth,int $requests,int $concurrency):array{$times=[];$errors=0;for($offset=0;$offset<$requests;$offset+=$concurrency){$multi=curl_multi_init();$handles=[];$batch=min($concurrency,$requests-$offset);for($i=0;$i<$batch;$i++){$h=curl_init($url);$options=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>15,CURLOPT_HTTPHEADER=>['Accept: application/json']];if($auth)$options[CURLOPT_HTTPHEADER][]='X-Access-Token: '.$token;curl_setopt_array($h,$options);curl_multi_add_handle($multi,$h);$handles[]=$h;}do{$status=curl_multi_exec($multi,$running);if($running)curl_multi_select($multi,1.0);}while($running&&$status===CURLM_OK);foreach($handles as $h){$code=(int)curl_getinfo($h,CURLINFO_RESPONSE_CODE);$times[]=(float)curl_getinfo($h,CURLINFO_TOTAL_TIME)*1000;if($code<200||$code>=300||curl_errno($h))$errors++;curl_multi_remove_handle($multi,$h);curl_close($h);}curl_multi_close($multi);}sort($times);return['p95_ms'=>round($times[(int)ceil(count($times)*.95)-1]??0,2),'average_ms'=>round(array_sum($times)/max(1,count($times)),2),'errors'=>$errors,'error_rate'=>round($errors/max(1,$requests)*100,2)];}
$failed=false;$results=[];foreach($tests as $name=>$test){$result=httpBatch($base.$test['url'],$token,$test['auth'],$requests,$concurrency);$result['target_ms']=$test['target'];$result['pass']=$result['p95_ms']<=$test['target']&&$result['error_rate']<=1;$failed=$failed||!$result['pass'];$results[$name]=$result;echo($result['pass']?'PASS ':'FAIL ').$name.' p95='.$result['p95_ms'].'ms errors='.$result['error_rate'].'% target='.$test['target']."ms\n";}echo json_encode(['success'=>!$failed,'requests_per_endpoint'=>$requests,'concurrency'=>$concurrency,'base_url'=>$base,'results'=>$results],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),"\n";exit($failed?1:0);
